/*
 * A269517  Lexicographically least sequence of nonnegative integers that
 *          avoids a/b-powers for all a/b >= 3/2.
 * https://oeis.org/A269517
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the lexicographically least nonnegative integer sequence
 *            that avoids a/b-powers for all a/b ≥ 3/2. It is generated by a
 *            greedy construction: at each index choose the smallest integer
 *            that does not create a forbidden block ending at that index. The
 *            algorithm keeps a static cache of already...
 * Range:     u8 n <= 108, u16 n <= 108, u32 n <= 108, u64 n <= 108,
 *            u128 n <= 108, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>

/* dynamic array that stores the prefix of the sequence already
   computed.  It is grown automatically whenever a new element
   beyond the current capacity is required.  */
static seq_t *seq_cache = NULL;
static size_t   seq_cap   = 0;  /* allocated capacity of seq_cache   */
static idx_t    seq_len   = 0;  /* number of elements computed so far */

/* --- utility: ensure the cache can contain at least 'need' slots. */
static void ensure_capacity(size_t need) {
    if (seq_cap >= need) return;
    size_t new_cap = seq_cap ? seq_cap : 16;
    while (new_cap < need) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
    seq_cache = tmp;
    seq_cap   = new_cap;
}

/* --- test whether the current sequence of length 'len' contains a
   forbidden a/b‑power (i.e. a block whose exponent ≥ 3/2).  */
static bool has_forbidden(const seq_t *seq, idx_t len) {
    /* examine every suffix ending at the last element of the prefix */
    for (idx_t L = 2; L <= len; ++L) {
        idx_t start = len - L;            /* start of the suffix            */
        idx_t maxP  = (2 * L) / 3;        /* largest allowed period (int.)  */
        for (idx_t p = 1; p <= maxP; ++p) {
            bool ok = true;
            /* check that the block is p‑periodic: all chars at
               distance p are equal until the end of the suffix. */
            for (idx_t j = 0; j + p < L; ++j) {
                if (seq[start + j] != seq[start + j + p]) {
                    ok = false;
                    break;
                }
            }
            if (ok)               /* a forbidden power was found   */
                return true;
        }
    }
    return false;                  /* no forbidden block detected      */
}

/* Public function requested by the problem. */
seq_t a(idx_t n) {
    /* initialise the cache on the first call */
    if (!seq_cache) {
        ensure_capacity(16);
        seq_len = 0;
    }

    /* extend the cached sequence up to index n if necessary */
    if (n >= seq_len) {
        for (idx_t pos = seq_len; pos <= n; ++pos) {
            ensure_capacity(pos + 1);          /* grow the cache if needed */

            seq_t cand = 0;                    /* try smallest candidates   */
            for (;;) {
                seq_cache[pos] = cand;
                if (!has_forbidden(seq_cache, pos + 1))
                    break;                     /* found a valid value       */
                ++cand;                        /* try next candidate        */
            }
        }
        seq_len = n + 1;
    }

    return seq_cache[n];
}
